/**
 * build-figures-index — produces docs/figures-index.md from the
 * filesystem.  Scans every `content/<paper>/<chapter>/rendered/*.svg`
 * (excluding auto-generated dvisvgm output, which the local/illustration-author
 * skill never produces), groups by chapter, and emits a master
 * catalogue for editorial review.
 *
 * Authoring rule (per local/illustration-author skill):
 *   <slug>.svg              — primary light-mode SVG  [REQUIRED]
 *   <slug>.dark.svg         — optional hand-tuned dark override
 *   <slug>.prompt.md        — prompt sidecar (margin note in PDF)
 *
 * A "figure family" = one slug; variants A/B/… within the same
 * recommended slot are detected by a -A/-B/… suffix on the slug
 * (case-insensitive single trailing letter).  Index groups variants
 * under one heading.
 *
 * Run:  bun run pipeline/build-figures-index.ts
 *
 * @module content/pipeline/build-figures-index
 */

import { readFileSync, writeFileSync, readdirSync, existsSync, statSync } from "fs";
import { join, basename, relative, dirname } from "path";

const REPO_ROOT = join(import.meta.dir, "..", "..");
const CONTENT_ROOT = join(REPO_ROOT, "content", "quantum-observable-universe");
const OUT = join(REPO_ROOT, "docs", "figures-index.md");

interface SvgEntry {
  slug: string;            // e.g. "roadmap-flow-A"
  family: string;          // e.g. "roadmap-flow" (slug with trailing -X stripped)
  variant?: string;        // e.g. "A"
  chapter: string;         // chapter dir name
  svgPath: string;         // path relative to repo root
  darkPath?: string;       // sibling .dark.svg if present
  promptPath?: string;     // sibling .prompt.md if present
  promptText?: string;
}

function isDvisvgmOutput(path: string): boolean {
  const head = readFileSync(path, "utf-8").slice(0, 200);
  return head.includes("generated by dvisvgm");
}

function listSvgsInChapter(chapterDir: string): string[] {
  const renderedDir = join(chapterDir, "rendered");
  if (!existsSync(renderedDir)) return [];
  return readdirSync(renderedDir)
    .filter((f) => f.endsWith(".svg") && !f.endsWith(".dark.svg"))
    .map((f) => join(renderedDir, f));
}

function parseSlug(filename: string): { slug: string; family: string; variant?: string } {
  const slug = basename(filename, ".svg");
  const m = slug.match(/^(.+)-([A-Z])$/);
  return m
    ? { slug, family: m[1], variant: m[2] }
    : { slug, family: slug };
}

function findChapters(): string[] {
  return readdirSync(CONTENT_ROOT)
    .filter((d) => {
      const p = join(CONTENT_ROOT, d);
      return statSync(p).isDirectory()
        && existsSync(join(p, "rendered"));
    })
    .sort();
}

function loadEntry(svgPath: string, chapter: string): SvgEntry | null {
  if (isDvisvgmOutput(svgPath)) return null;
  const { slug, family, variant } = parseSlug(svgPath);
  const dirPath = dirname(svgPath);
  const darkPath = join(dirPath, `${slug}.dark.svg`);
  const promptPath = join(dirPath, `${slug}.prompt.md`);
  return {
    slug,
    family,
    variant,
    chapter,
    svgPath: relative(REPO_ROOT, svgPath),
    darkPath: existsSync(darkPath) ? relative(REPO_ROOT, darkPath) : undefined,
    promptPath: existsSync(promptPath) ? relative(REPO_ROOT, promptPath) : undefined,
    promptText: existsSync(promptPath)
      ? readFileSync(promptPath, "utf-8").trim()
      : undefined,
  };
}

function relFromIndex(repoRelativePath: string): string {
  // docs/figures-index.md → repo paths need ../ prefix
  return `../${repoRelativePath}`;
}

function chapterTitle(chapter: string): string {
  // turn "braids-and-knots" into "Braids and Knots"
  return chapter
    .split("-")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");
}

function summary(promptText: string, maxLen = 220): string {
  const oneLine = promptText.replace(/\s+/g, " ").trim();
  return oneLine.length > maxLen
    ? oneLine.slice(0, maxLen - 1).trimEnd() + "…"
    : oneLine;
}

function main() {
  const chapters = findChapters();
  const entriesByChapter: Map<string, SvgEntry[]> = new Map();
  let totalAuthored = 0;
  let totalDarkOverrides = 0;

  for (const chapter of chapters) {
    const chapterDir = join(CONTENT_ROOT, chapter);
    const svgs = listSvgsInChapter(chapterDir);
    const entries = svgs
      .map((p) => loadEntry(p, chapter))
      .filter((e): e is SvgEntry => e !== null)
      .sort((a, b) => a.slug.localeCompare(b.slug));
    if (entries.length === 0) continue;
    entriesByChapter.set(chapter, entries);
    totalAuthored += entries.length;
    totalDarkOverrides += entries.filter((e) => e.darkPath).length;
  }

  const lines: string[] = [];
  lines.push("# Figures index — *On the Mechanics of Quantum Observable Universes*");
  lines.push("");
  lines.push("Auto-generated by");
  lines.push("[`content/pipeline/build-figures-index.ts`](../content/pipeline/build-figures-index.ts).");
  lines.push("Do not edit by hand — re-run the script after adding or modifying");
  lines.push("a figure under `content/quantum-observable-universe/<chapter>/rendered/`.");
  lines.push("");
  lines.push("**Authoring source-of-truth:**");
  lines.push("- Specification + placement: [`docs/illustration-recommendations.md`](illustration-recommendations.md)");
  lines.push("- Skill (prompt → SVG): [`.claude/skills/local/illustration-author.md`](../.claude/skills/local/illustration-author.md)");
  lines.push("- Coordination ledger: [`docs/coordination/illustrations.md`](coordination/illustrations.md)");
  lines.push("");
  lines.push(`**Status:** ${totalAuthored} authored figures (across ${entriesByChapter.size} chapters); ${totalDarkOverrides} hand-tuned dark-mode override(s).`);
  lines.push("");
  lines.push("Variants of the same recommended slot share a slug-family (e.g. `roadmap-flow-A`, `roadmap-flow-B`) and are grouped together below; the variant currently embedded in the paper is listed first.");
  lines.push("");
  lines.push("---");
  lines.push("");

  for (const chapter of chapters) {
    const entries = entriesByChapter.get(chapter);
    if (!entries) continue;

    lines.push(`## ${chapterTitle(chapter)}`);
    lines.push("");

    // Group by family
    const byFamily: Map<string, SvgEntry[]> = new Map();
    for (const e of entries) {
      if (!byFamily.has(e.family)) byFamily.set(e.family, []);
      byFamily.get(e.family)!.push(e);
    }

    for (const [family, members] of byFamily) {
      members.sort((a, b) => (a.variant ?? "").localeCompare(b.variant ?? ""));
      const isMulti = members.length > 1;

      lines.push(`### ${family}${isMulti ? `  (${members.length} variants)` : ""}`);
      lines.push("");

      for (const e of members) {
        const tag = e.variant ? `**variant ${e.variant}** — ` : "";
        const darkTag = e.darkPath ? "  •  *hand-tuned dark override*" : "";
        lines.push(`${tag}\`${e.slug}\`${darkTag}`);
        lines.push("");
        if (e.promptText) {
          lines.push("> " + summary(e.promptText));
          lines.push("");
        }
        lines.push(`![${e.slug}](${relFromIndex(e.svgPath)})`);
        lines.push("");
        if (e.darkPath) {
          lines.push(`<sub>dark override: [\`${basename(e.darkPath)}\`](${relFromIndex(e.darkPath)})</sub>`);
          lines.push("");
        }
        if (e.promptPath) {
          lines.push(`<sub>prompt: [\`${basename(e.promptPath)}\`](${relFromIndex(e.promptPath)})</sub>`);
          lines.push("");
        }
      }
      lines.push("---");
      lines.push("");
    }
  }

  lines.push("");
  lines.push(`<sub>Generated ${new Date().toISOString().slice(0, 10)} from ${totalAuthored} authored SVG file(s).</sub>`);
  lines.push("");

  writeFileSync(OUT, lines.join("\n"));
  console.log(`✓ Wrote ${relative(REPO_ROOT, OUT)} — ${totalAuthored} figures across ${entriesByChapter.size} chapters.`);
}

main();
